  act(() => control.focus());
  expect(screen.getByTestId('root')).toHaveAttribute('data-focused', '');
  act(() => { (screen.getByRole('button') as HTMLButtonElement).click(); });
  console.log('P2 disabled attr', control.hasAttribute('disabled'), 'activeElement is control', document.activeElement === control, 'root data-focused =', screen.getByTestId('root').getAttribute('data-focused'));
  cleanup();
});

