    const [value, setValue] = React.useState('');
    return (
      <Field.Root data-testid="root" validationMode="onChange" validate={validate as any}>
        <Field.Control value={value} onValueChange={setValue} />
        <Field.Error data-testid="err" />
        <button type="button" onClick={() => setValue('')}>clear</button>
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'bad' } });
  fireEvent.click(screen.getByRole('button'));
  console.log('P3 validate calls', validate.mock.calls.map((c) => c[0]));
  await act(async () => { resolvers[0]?.('stale error'); await Promise.resolve(); });
  await act(async () => { resolvers[1]?.(null); await Promise.resolve(); });
